array_index:
recursive fn make()->i64[2]{return[7,8];}
recursive fn index()->i64{var scratch:i64[2]=[99,100];return scratch[0]-98;}
fn main(){assert(make()[index()]==8);print("array_index");}

struct_field:
struct S{n:i64}
recursive fn make()->S{return S{n:7};}
fn main(){assert(make().n==7);print("struct_field");}

array_nominal_field:
struct S{n:i64}
recursive fn make()->S[2]{return[S{n:7},S{n:8}];}
recursive fn index()->i64{var scratch:i64[2]=[99,100];return scratch[0]-98;}
fn main(){assert(make()[index()].n==8);print("array_nominal_field");}

field_array_index:
struct H{items:i64[2]}
recursive fn make()->H{return H{items:[7,8]};}
recursive fn index()->i64{var scratch:i64[2]=[99,100];return scratch[0]-98;}
fn main(){assert(make().items[index()]==8);print("field_array_index");}
